```mermaid
classDiagram
    class Calculator {
        +calculate(expression: str) -> str
        -parse(expression: str) -> list
        -evaluate(tokens: list) -> float
        -format_result(value: float) -> str
    }
    class ExpressionParser {
        +parse(expression: str) -> list
    }
    class ExpressionEvaluator {
        +evaluate(tokens: list) -> float
    }
    class ResultFormatter {
        +format(value: float) -> str
    }
    class Token {
        -type: str
        -value: any
        +__init__(type: str, value: any)
    }
    class MathExpression {
        -raw_text: str
        -parsed_tokens: list
        -result: float
        +__init__(raw_text: str)
        +parse()
        +evaluate()
        +format_result() -> str
    }
    class CLI {
        +run()
        -get_input() -> str
        -display_result(result: str)
        -display_error(error: str)
    }
    Calculator --> ExpressionParser
    Calculator --> ExpressionEvaluator
    Calculator --> ResultFormatter
    ExpressionParser ..> Token : creates
    ExpressionEvaluator ..> Token : uses
    MathExpression --> Token : contains
    CLI --> Calculator
```

